1	import { http, HttpResponse, delay } from "msw";
2	
3	const BASE_URL = "https://api.example.com/v1";
4	const VALID_API_KEY = "test_key";
5	
6	type PaymentStatus = "pending" | "succeeded" | "canceled" | "refunded" | "partially_refunded";
7	
8	interface StoredPayment {
9	  id: string;
10	  amount: number;
11	  currency: string;
12	  source: string;
13	  status: PaymentStatus;
14	  amountRefunded: number;
15	  createdAt: string;
16	}
17	
18	const payments = new Map<string, StoredPayment>();
19	
20	export function resetPayments() {
21	  payments.clear();
22	}
23	
24	function errorResponse(status: number, code: string, message: string) {
25	  return HttpResponse.json({ error: { code, message } }, { status });
26	}
27	
28	function isAuthorized(request: Request) {
29	  return request.headers.get("Authorization") === `Bearer ${VALID_API_KEY}`;
30	}
31	
32	const unauthorized = () => errorResponse(401, "unauthorized", "Missing or invalid API key");
33	
34	const notFound = (id: string) =>
35	  errorResponse(404, "payment_not_found", `No payment with id ${id}`);
36	
37	export const handlers = [
38	  http.get("https://api.example.com/user", () => {
39	    return HttpResponse.json({
40	      id: "abc-123",
41	      firstName: "John",
42	      lastName: "Maverick",
43	    });
44	  }),
45	
46	  // 1. Create a payment. The `source` token selects the simulated outcome.
47	  http.post(`${BASE_URL}/payments`, async ({ request }) => {
48	    if (!isAuthorized(request)) {
49	      return unauthorized();
50	    }
51	
52	    const body = (await request.json().catch(() => null)) as {
53	      amount?: unknown;
54	      currency?: unknown;
55	      source?: unknown;
56	    } | null;
57	
58	    if (
59	      !body ||
60	      typeof body.amount !== "number" ||
61	      !Number.isInteger(body.amount) ||
62	      body.amount <= 0 ||
63	      typeof body.currency !== "string" ||
64	      typeof body.source !== "string"
65	    ) {
66	      return errorResponse(
67	        400,
68	        "invalid_request",
69	        "amount (positive integer), currency and source are required",
70	      );
71	    }
72	
73	    switch (body.source) {
74	      case "tok_chargeDeclined":
75	        return errorResponse(402, "card_declined", "The card was declined");
76	      case "tok_insufficientFunds":
77	        return errorResponse(402, "insufficient_funds", "The card has insufficient funds");
78	      case "tok_serverError":
79	        return errorResponse(
80	          500,
81	          "processing_error",
82	          "An error occurred while processing the payment",
83	        );
84	      case "tok_timeout":
85	        await delay(10_000);
86	        break;
87	      case "tok_visa":
88	      case "tok_pending":
89	        break;
90	      default:
91	        return errorResponse(400, "invalid_source", "Unknown payment source");
92	    }
93	
94	    const payment: StoredPayment = {
95	      id: `pay_${crypto.randomUUID()}`,
96	      amount: body.amount,
97	      currency: body.currency,
98	      source: body.source,
99	      status: body.source === "tok_pending" ? "pending" : "succeeded",
100	      amountRefunded: 0,
101	      createdAt: new Date().toISOString(),
102	    };
103	    payments.set(payment.id, payment);
104	    return HttpResponse.json(payment, { status: 201 });
105	  }),
106	
107	  // 2. Retrieve a payment.
108	  http.get(`${BASE_URL}/payments/:id`, ({ request, params }) => {
109	    if (!isAuthorized(request)) {
110	      return unauthorized();
111	    }
112	    const payment = payments.get(params["id"] as string);
113	    if (!payment) {
114	      return notFound(params["id"] as string);
115	    }
116	    return HttpResponse.json(payment);
117	  }),
118	
119	  // 3. List payments, optionally filtered by status.
120	  http.get(`${BASE_URL}/payments`, ({ request }) => {
121	    if (!isAuthorized(request)) {
122	      return unauthorized();
123	    }
124	    const status = new URL(request.url).searchParams.get("status");
